def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count outcomes
    cc = cd = dc = dd = 0
    for me, opp in history:
        if me == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    last_me, last_opp = history[-1]

    # Opponent cooperation rate
    opp_c = cc + dc
    opp_coop_rate = opp_c / n

    # If opponent has been very cooperative, reciprocate cooperatively.
    if opp_coop_rate >= 0.85:
        return 'C'

    # If opponent has been very exploitative, defect.
    if opp_coop_rate <= 0.25:
        return 'D'

    # Defect if opponent just defected after we cooperated (punish).
    if last_me == 'C' and last_opp == 'D':
        return 'D'

    # If opponent just cooperated after we defected, return to cooperation.
    if last_me == 'D' and last_opp == 'C':
        return 'C'

    # Near the end, exploit more: if opponent often cooperates, defect for payoff.
    if n >= 90:
        if opp_coop_rate >= 0.5:
            return 'D'
        # otherwise continue tit-for-tat-ish
        if last_opp == 'C':
            return 'C'
        return 'D'

    # Moderate regime: tit-for-tat with slight forgiveness.
    if last_opp == 'C':
        return 'C'

    # Opponent defected; defect unless they are otherwise fairly cooperative.
    if opp_coop_rate > 0.6 and rng.random() < 0.25:
        return 'C'
    return 'D'
